import type { Generator, ProjectGraph, Tree } from '@nx/devkit';
import type { REPORTER_NAME as NonProjectFilesReporterName, Violation as NonProjectFilesViolation } from './reporters/non-project-files-reporter';
import type { REPORTER_NAME as ProjectFilesReporterName, Violation as ProjectFilesViolation } from './reporters/project-files-reporter';
import type { REPORTER_NAME as ProjectReporterName, Violation as ProjectViolation } from './reporters/project-reporter';
export interface NxJsonConformanceConfiguration {
    /**
     * Optional path to write the conformance results to, defaults to "dist/conformance-result.json".
     * Set to false to disable writing the conformance results to a file.
     */
    outputPath?: string | false;
    rules: {
        /**
         * Relative path to a local rule implementation, node_module path or nx-cloud rule ID for Nx Cloud Enterprise.
         */
        rule: string;
        /**
         * Rule specific configuration options.
         */
        options?: Record<string, unknown>;
        /**
         * The projects array allows users to opt in or out of violations for specific projects being reported by the current rule.
         * The array can contain any valid matchers for findMatchingProjects(), by default the implied value is ["*"].
         *
         * We additionally provide an object syntax for projects which allows users to provide by a matcher string and an
         * explanation to communicate to their colleagues why a particular project or projects was included or excluded from
         * consideration from the rule.
         *
         * The explanation currently does nothing to affect any functionality.
         */
        projects?: RuleProjectsConfig;
        /**
         * Optional explanation field for users to be able to communicate to their colleague why a particular rule is
         * enabled and important to the workspace in question.
         *
         * Currently does nothing to affect any functionality.
         */
        explanation?: string;
        /**
         * Override the default status of the rule, which is "enforced".
         *
         * If set to "evaluated", the rule will be reported as normal, but not enforced (will exit with code 0).
         * If set to "disabled", the rule will not be evaluated at all.
         */
        status?: RuleStatus;
    }[];
}
export type ConformanceViolation = {
    message: string;
};
export type RuleStatus = 'enforced' | 'evaluated' | 'disabled';
export type RuleProjectsConfig = Array<string | {
    matcher: string;
    explanation: string;
}>;
type ReporterDetailsMap = {
    [ProjectReporterName]: {
        violations: ProjectViolation[];
    };
    [ProjectFilesReporterName]: {
        violations: ProjectFilesViolation[];
    };
    [NonProjectFilesReporterName]: {
        violations: NonProjectFilesViolation[];
    };
};
export type ValidReporter = keyof ReporterDetailsMap;
export type ConformanceRuleResult<Reporter extends ValidReporter> = {
    severity: ConformanceRuleResultSeverity;
    details: ReporterDetailsMap[Reporter];
};
export interface ConformanceRuleContext<RuleOptions> {
    projectGraph: ProjectGraph;
    ruleOptions: RuleOptions;
}
/**
 * NOTE: In the case where the rule status is "disabled", the severity will be set imperatively by the rule
 * runner to `null`, but it is not a valid severity for a rule to return, so it is not included in the type.
 */
export type ConformanceRuleResultSeverity = 'high' | 'medium' | 'low';
export type ConformanceRuleCategory = 'consistency' | 'maintainability' | 'reliability' | 'security';
type GeneratorWithTypedTree<T = unknown> = (tree: Tree, schema: T) => ReturnType<Generator<T>>;
export type ConformanceRuleFixGenerator<Reporter extends ValidReporter> = GeneratorWithTypedTree<{
    violations: ReporterDetailsMap[Reporter]['violations'];
}>;
export type ConformanceRuleBase<RuleOptions, Reporter extends ValidReporter> = {
    name: string;
    category: ConformanceRuleCategory;
    description: string;
    reporter: Reporter;
    implementation: (context: ConformanceRuleContext<RuleOptions>) => Promise<ConformanceRuleResult<Reporter>>;
    /**
     * Optional nx generator implementation intended to fix the the violations reported by the rule.
     */
    fixGenerator?: ConformanceRuleFixGenerator<Reporter>;
};
type ConformanceRuleMap<RuleOptions> = {
    [Reporter in ValidReporter]: ConformanceRuleBase<RuleOptions, Reporter>;
};
export type ConformanceRule<RuleOptions> = ConformanceRuleMap<RuleOptions>[ValidReporter];
export type ConformanceRuleResultWithRuleAndRunnerData<Reporter extends ValidReporter> = ConformanceRuleResult<Reporter> & {
    ruleData: Omit<ConformanceRuleBase<any, Reporter>, 'implementation' | 'fixGenerator'>;
    runnerData: {
        status: RuleStatus;
        fixGeneratorStatus: 'no-fix-generator' | 'applied' | 'not-applied';
        countOfOriginalViolations: number;
        countOfViolationsFixedByGenerator: number;
        countOfViolationsFilteredByProjects: number;
    };
};
export type ConformanceReporter<Reporter extends ValidReporter> = (data: {
    result: ConformanceRuleResultWithRuleAndRunnerData<Reporter>;
}) => void;
export {};
